// One item per search: the endpoint, the keyword, and the order and time filters it takes.
return [
  { json: { endpoint: 'douyin.videos.search', params: { query: 'cold brew', sort: 'popular', published_within: 'week' } } },
  { json: { endpoint: 'xiaohongshu.notes.search', params: { query: 'cold brew', sort: 'popular', published_within: 'week' } } },
  { json: { endpoint: 'wechat.posts.search', params: { query: 'cold brew', sort: 'popular', published_within: 'week' } } },
];

const lines = [];
for (const page of $input.all()) {
  const { endpoint, params } = page.json;
  const items = (page.json.data && page.json.data.items) || [];
  const top = items
    .slice()
    .sort((a, b) => ((b.metrics && b.metrics.likes) || 0) - ((a.metrics && a.metrics.likes) || 0))
    .slice(0, 5);
  lines.push(`*${params.query}* (${endpoint.split('.')[0]})`);
  for (const p of top) {
    lines.push(`- ${(p.title || p.text || '').slice(0, 80)} (${(p.metrics && p.metrics.likes) || 0} likes) ${p.url || ''}`);
  }
}
return [{ json: { text: lines.join('\n') } }];
